// Společné bezpečné chování webu. Tento soubor nesmí měnit pořadí článků,
// titulní hero ani redakční texty.

// NK_AD_FALLBACK_CONTRACT_20260908_V1
// Chybějící banner se nesmí zobrazit jako obří bezejmenný gradient.
(() => {
  'use strict';
  const installStyle = () => {
    if (document.getElementById('nk-ad-fallback-contract-style')) return;
    const style = document.createElement('style');
    style.id = 'nk-ad-fallback-contract-style';
    style.textContent = `
      .nk-ad-generated-card.promo-card-wide.promo-card-full-image{display:block!important;height:auto!important;min-height:0!important;max-height:none!important;aspect-ratio:auto!important;overflow:hidden!important;background:#fff!important;border:1px solid #d9e1e5!important;border-radius:18px!important;box-shadow:0 10px 28px rgba(18,35,45,.10)!important}
      .nk-ad-generated-card.promo-card-wide.promo-card-full-image .promo-banner,.nk-ad-generated-card.promo-card-wide.promo-card-full-image>.nk-ad-generated-visual,.nk-ad-generated-card.promo-card-wide.promo-card-full-image .promo-banner .nk-ad-generated-visual{display:none!important;height:0!important;min-height:0!important;aspect-ratio:auto!important}
      .nk-ad-generated-card.promo-card-wide.promo-card-full-image .promo-wide-copy,.nk-ad-generated-card.promo-card-wide .promo-wide-copy,.nk-ad-generated-card .nk-ad-safe-copy{display:flex!important;visibility:visible!important;opacity:1!important;flex-direction:column!important;justify-content:center!important;align-items:flex-start!important;gap:7px!important;min-height:150px!important;height:auto!important;padding:22px 26px!important;box-sizing:border-box!important;background:#fff!important;color:#17242d!important;text-align:left!important}
      .nk-ad-generated-card .promo-wide-copy small,.nk-ad-generated-card .nk-ad-safe-copy small{display:block!important;color:#6c7780!important;font-size:12px!important;font-weight:900!important;letter-spacing:.07em!important;text-transform:uppercase!important}
      .nk-ad-generated-card .promo-wide-copy strong,.nk-ad-generated-card .nk-ad-safe-copy strong{display:block!important;color:#17242d!important;font:900 24px/1.18 Georgia,serif!important}
      .nk-ad-generated-card .promo-wide-copy .promo-description,.nk-ad-generated-card .nk-ad-safe-copy .promo-description{display:block!important;color:#52616a!important;font-size:15px!important;line-height:1.5!important}
      .nk-ad-generated-card .promo-wide-copy b,.nk-ad-generated-card .nk-ad-safe-copy b{display:inline-block!important;margin-top:4px!important;padding:9px 13px!important;border-radius:999px!important;background:#9f2626!important;color:#fff!important;font-size:13px!important;line-height:1.2!important}
      .nk-ad-generated-card.article-rail-card .article-rail-fallback,.nk-ad-generated-card.article-rail-card .article-rail-copy{display:block!important;visibility:visible!important;opacity:1!important}
      .nk-ad-generated-card.promo-card-wide:not(.promo-card-full-image) .nk-ad-generated-visual{max-height:240px!important;aspect-ratio:3/1!important}
      @media(max-width:700px){.nk-ad-generated-card.promo-card-wide.promo-card-full-image .promo-wide-copy,.nk-ad-generated-card.promo-card-wide .promo-wide-copy,.nk-ad-generated-card .nk-ad-safe-copy{min-height:132px!important;padding:18px 19px!important}.nk-ad-generated-card .promo-wide-copy strong,.nk-ad-generated-card .nk-ad-safe-copy strong{font-size:21px!important}}
    `;
    (document.head || document.documentElement).appendChild(style);
  };
  const safeTitle = (card) => {
    const existing = card.querySelector('strong,h3,.ad-title,.article-rail-fallback');
    const text = existing && String(existing.textContent || '').trim();
    if (text && !/^reklama$/i.test(text)) return text;
    const aria = String(card.getAttribute('aria-label') || '').replace(/^reklama:\s*/i, '').trim();
    if (aria) return aria;
    try { const host = new URL(card.getAttribute('href') || '', location.href).hostname.replace(/^www\./, ''); return host || 'Nabídka partnera'; }
    catch (_) { return 'Nabídka partnera'; }
  };
  const ensureCopy = (card) => {
    if (!(card instanceof Element) || !card.classList.contains('nk-ad-generated-card')) return;
    if (card.matches('a.promo-card') && !card.querySelector('.promo-wide-copy,.nk-ad-safe-copy')) {
      const copy=document.createElement('span'); copy.className='nk-ad-safe-copy';
      const tag=document.createElement('small'); tag.textContent='REKLAMA';
      const strong=document.createElement('strong'); strong.textContent=safeTitle(card);
      const desc=document.createElement('span'); desc.className='promo-description'; desc.textContent='Aktuální nabídku a podmínky najdete po kliknutí u partnera.';
      const cta=document.createElement('b'); cta.textContent='Zjistit více →';
      copy.append(tag,strong,desc,cta); card.appendChild(copy);
    }
    if (card.matches('a.article-rail-card') && !card.querySelector('.article-rail-fallback,.article-rail-copy,strong,h3')) {
      const fallback=document.createElement('span'); fallback.className='article-rail-fallback'; fallback.textContent=safeTitle(card); card.appendChild(fallback);
    }
  };
  const repair = (root=document) => {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    if (root instanceof Element && root.classList.contains('nk-ad-generated-card')) ensureCopy(root);
    root.querySelectorAll('.nk-ad-generated-card').forEach(ensureCopy);
  };
  const start = () => {
    installStyle(); repair();
    if (!document.documentElement) return;
    new MutationObserver((mutations) => {
      for (const mutation of mutations) {
        if (mutation.type==='attributes' && mutation.target instanceof Element) ensureCopy(mutation.target);
        for (const node of mutation.addedNodes) if (node instanceof Element) repair(node);
      }
    }).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});
    [250,800,1800,3500].forEach((delay)=>setTimeout(()=>repair(),delay));
  };
  if (document.readyState==='loading') document.addEventListener('DOMContentLoaded',start,{once:true}); else start();
})();
